/**
 * Brings a deleted workspace back. There is no `Actor` to resolve while the
 * workspace is deleted, so the caller is named by user id and checked against
 * the membership row that deletion left in place.
 *
 * A workspace that was never deleted is returned as it stands. Once the
 * retention window has closed the workspace is gone, purge or not.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  const member = await memberRepo.findMember(orgId, userId);
  if (!member) {
    throw new NotFoundError("Organization", orgId);
  }

  if (org.archivedAt !== null && retentionClosed(org.archivedAt)) {
    throw new NotFoundError("Organization", orgId);
  }

  assertCan(
    { userId, orgId, role: member.role },
    "org:restore",
    orgResource(orgId),
  );

  if (org.archivedAt === null) return org;

  const restored = await orgRepo.restoreOrg(orgId);

  await emit("organization.restored", {
    ...envelope(restored.id, userId),
    slug: restored.slug,
  });

  return restored;
}

/** True once `DELETED_WORKSPACE_RETENTION_DAYS` have elapsed since deletion. */
function retentionClosed(archivedAt: string, now: Date = new Date()): boolean {
  const cutoff = toIsoTimestamp(
    new Date(now.getTime() - DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY),
  );
  return archivedAt <= cutoff;
}

